// Title: Log the number of row fields in a refreshed PivotTable with Aspose.Cells for .NET (C#)
// Common Searches: C# Aspose.Cells how to get row field count after refreshing a PivotTable | log PivotTable row fields count for performance monitoring using Aspose.Cells | retrieve number of rows generated by PivotTable.CalculateData in .NET | Aspose.Cells example to display row field count after PivotTable.RefreshData | diagnose PivotTable size after refresh with Aspose.Cells C# code
// Tags: Aspose.Cells PivotTable row fields count | RefreshData CalculateData PivotTable C# | PivotTable performance diagnostics Aspose.Cells | log PivotTable row count .NET | Excel PivotTable row field metric Aspose

using System;
using System.IO;
using Aspose.Cells;
using Aspose.Cells.Pivot; // Ensure PivotTable types are available

// The sample loads an Excel workbook, checks for a PivotTable on the first worksheet, refreshes its data source, recalculates the layout, obtains the count of row fields as an approximate row count, writes the count to the console for diagnostics, and saves the workbook while handling file‑related and runtime errors.
class PivotTableRowLogger
{
    static void Main()
    {
        try
        {
            string inputPath = "input.xlsx";
            string outputPath = "output.xlsx";

            // Verify that the input file exists to avoid FileNotFoundException
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Input file '{inputPath}' not found.");
                return;
            }

            // Load the workbook containing the PivotTable
            Workbook workbook = new Workbook(inputPath);

            // Access the first worksheet (adjust index if needed)
            Worksheet worksheet = workbook.Worksheets[0];

            // Ensure the worksheet contains at least one PivotTable
            if (worksheet.PivotTables == null || worksheet.PivotTables.Count == 0)
            {
                Console.WriteLine("No PivotTables found in the worksheet.");
                return;
            }

            // Retrieve the first PivotTable on the worksheet
            PivotTable pivotTable = worksheet.PivotTables[0];

            // Refresh the PivotTable data source and recalculate its layout
            pivotTable.RefreshData();
            pivotTable.CalculateData();

            // After refresh, obtain an approximate row count.
            // Aspose.Cells PivotTable does not expose a direct RowCount property,
            // so we use the count of row fields as a representative metric.
            int rowCount = pivotTable.RowFields.Count;

            // Log the row count for performance monitoring and diagnostics
            Console.WriteLine($"PivotTable '{pivotTable.Name}' has {rowCount} row fields after refresh.");

            // Save the workbook if any changes need to be persisted
            try
            {
                workbook.Save(outputPath);
                Console.WriteLine($"Workbook saved to '{outputPath}'.");
            }
            catch (Exception saveEx)
            {
                Console.WriteLine($"Failed to save workbook: {saveEx.Message}");
            }
        }
        catch (Exception ex)
        {
            // Catch any unexpected errors and display a friendly message
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
